previewCss:
.darma-loader-darma-b14-curtain-reveal { --accent: var(--loader-color, #b91c1c); --accent-2: var(--loader-secondary-color, #facc15); width: var(--loader-size, 124px); height: calc(var(--loader-size, 124px) * .72); position: relative; overflow: hidden; border-radius: 4px; background: radial-gradient(circle at 50% 62%, color-mix(in srgb, #fff 62%, var(--accent-2)) 0 20%, color-mix(in srgb, #000 44%, var(--accent-2)) 72%); }
.darma-loader-darma-b14-curtain-reveal::before { content: ''; position: absolute; z-index: 3; top: 0; left: 0; width: 100%; height: 15%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 32%, var(--accent))); box-shadow: 0 2px 5px rgba(15, 23, 42, .35); }
.darma-loader-darma-b14-curtain-reveal span { position: absolute; top: 0; height: 100%; width: 52%; background: repeating-linear-gradient(90deg, var(--accent) 0 7%, color-mix(in srgb, #000 28%, var(--accent)) 7% 14%); }
.darma-loader-darma-b14-curtain-reveal span:nth-child(1) { left: 0; animation: darma-loader-darma-b14-curtain-reveal-part-left calc(var(--loader-speed, 1s) * 3.2) ease-in-out infinite; }
.darma-loader-darma-b14-curtain-reveal span:nth-child(2) { right: 0; animation: darma-loader-darma-b14-curtain-reveal-part-right calc(var(--loader-speed, 1s) * 3.2) ease-in-out infinite; }
@keyframes darma-loader-darma-b14-curtain-reveal-part-left { 0%, 14% { transform: translateX(0); } 44%, 66% { transform: translateX(-86%); } 92%, 100% { transform: translateX(0); } }
@keyframes darma-loader-darma-b14-curtain-reveal-part-right { 0%, 14% { transform: translateX(0); } 44%, 66% { transform: translateX(86%); } 92%, 100% { transform: translateX(0); } }

